package com.hbm.client.silex;
import com.hbm.client.model.*;import com.hbm.machine.silex.*;import com.hbm.multiblock.DummyableBlock;import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.math.Axis;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.blockentity.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.phys.AABB;
/** Original smooth authored HFR model/UV and source four yaw values. */
public final class SilexRenderer implements BlockEntityRenderer<SilexBlockEntity> {
 static final ResourceLocation MODEL=SilexContent.id("models/machines/silex.obj"),TEXTURE=SilexContent.id("textures/models/machines/silex.png");public SilexRenderer(BlockEntityRendererProvider.Context context){}
 static void model(PoseStack poses,MultiBufferSource buffers,int light,int overlay){LegacyObjRenderer.renderAll(LegacyObjModels.INSTANCE.get(Minecraft.getInstance().getResourceManager(),MODEL),poses,buffers.getBuffer(RenderType.entityCutout(TEXTURE)),light,overlay,-1,LegacyObjRenderer.Convention.HFR);}
 @Override public void render(SilexBlockEntity machine,float partial,PoseStack poses,MultiBufferSource buffers,int light,int overlay){int angle=switch(DummyableBlock.facing(machine.getBlockState())){case NORTH->90;case WEST->180;case SOUTH->270;default->0;};LegacyContactShadows.render(machine,LegacyObjModels.INSTANCE.get(Minecraft.getInstance().getResourceManager(),MODEL),new org.joml.Matrix4f().translation(.5F,0,.5F).rotateY((float)Math.toRadians(angle)),poses,buffers);poses.pushPose();poses.translate(.5,0,.5);poses.mulPose(Axis.YP.rotationDegrees(angle));model(poses,buffers,light,overlay);poses.popPose();}
 @Override public boolean shouldRenderOffScreen(SilexBlockEntity machine){return true;}@Override public int getViewDistance(){return 256;}@Override public AABB getRenderBoundingBox(SilexBlockEntity machine){var p=machine.getBlockPos();return new AABB(p.getX()-1,p.getY(),p.getZ()-1,p.getX()+2,p.getY()+3,p.getZ()+2);}
}
